import { listTools, callTool } from './server.mjs';
const assert = (cond, msg) => { if (!cond) { console.error('FAIL:', msg); process.exit(1); } };

const tools = await listTools();
assert(tools.length === 3, '3 tools');
for (const t of tools) assert(t.inputSchema.additionalProperties === false, 'additionalProperties false on ' + t.name);

await callTool('begin_session', { session_id: 's1' });
await callTool('begin_session', { session_id: 's2' });
await callTool('put_value', { session_id: 's1', key: 'k', value: 'one' });
let cross = false;
try { await callTool('get_value', { session_id: 's2', key: 'k' }); } catch { cross = true; }
assert(cross, 'cross-session read rejected');

const res = await callTool('get_value', { session_id: 's1', key: 'k' });
assert(res.content[0].text === 'one', 'own read works');

let miss = false;
try { await callTool('get_value', { session_id: 's3', key: 'k' }); } catch { miss = true; }
assert(miss, 'missing session rejected');

let pmiss = false;
try { await callTool('put_value', { session_id: 's9', key: 'k', value: 'v' }); } catch { pmiss = true; }
assert(pmiss, 'put on missing session rejected');

let unk = false;
try { await callTool('nope', {}); } catch { unk = true; }
assert(unk, 'unknown tool rejected');

let extra = false;
try { await callTool('begin_session', { session_id: 's', extra: 1 }); } catch { extra = true; }
assert(extra, 'extra arg rejected');

let empty = false;
try { await callTool('begin_session', { session_id: '' }); } catch { empty = true; }
assert(empty, 'empty session_id rejected');

let badval = false;
try { await callTool('put_value', { session_id: 's1', key: 'k', value: 5 }); } catch { badval = true; }
assert(badval, 'non-string value rejected');

let missarg = false;
try { await callTool('put_value', { session_id: 's1', key: 'k' }); } catch { missarg = true; }
assert(missarg, 'missing value arg rejected');

console.log('ALL EDGE CHECKS PASSED');

