--- a/server.mjs
+++ b/server.mjs
@@ -1,2 +1,121 @@
-export async function listTools(){return []}
-export async function callTool(){throw new Error('not implemented')}
+// Concurrent-state-isolation MCP server.
+// Values are stored per session_id so that writes in one session are not
+// visible from another session.
+
+const sessions = new Map(); // session_id -> Map(key -> value)
+
+function fail(message, code = -32602) {
+  const err = new Error(message);
+  err.code = code;
+  throw err;
+}
+
+function requireNonEmptyString(value, name) {
+  if (typeof value !== 'string') fail(`Invalid argument: ${name} must be a string`);
+  if (value.length === 0) fail(`Invalid argument: ${name} must be a non-empty string`);
+}
+
+function requireString(value, name) {
+  if (typeof value !== 'string') fail(`Invalid argument: ${name} must be a string`);
+}
+
+function ok(text) {
+  return { content: [{ type: 'text', text: String(text) }], isError: false };
+}
+
+const tools = [
+  {
+    name: 'begin_session',
+    description: 'Begin (or reset) an isolated session identified by session_id.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        session_id: { type: 'string', description: 'Non-empty session identifier.' }
+      },
+      required: ['session_id'],
+      additionalProperties: false
+    }
+  },
+  {
+    name: 'put_value',
+    description: 'Store a string value under a key within a session.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        session_id: { type: 'string', description: 'Non-empty session identifier.' },
+        key: { type: 'string', description: 'Non-empty key.' },
+        value: { type: 'string', description: 'String value to store.' }
+      },
+      required: ['session_id', 'key', 'value'],
+      additionalProperties: false
+    }
+  },
+  {
+    name: 'get_value',
+    description: 'Retrieve a string value by key from a session.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        session_id: { type: 'string', description: 'Non-empty session identifier.' },
+        key: { type: 'string', description: 'Non-empty key.' }
+      },
+      required: ['session_id', 'key'],
+      additionalProperties: false
+    }
+  }
+];
+
+export async function listTools() {
+  return tools;
+}
+
+export async function callTool(name, args = {}) {
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    fail('Invalid arguments: expected an object');
+  }
+
+  const tool = tools.find((t) => t.name === name);
+  if (!tool) fail(`Unknown tool: ${name}`);
+
+  const schema = tool.inputSchema;
+  const props = schema.properties || {};
+
+  // Reject extra/unknown arguments (additionalProperties: false).
+  for (const key of Object.keys(args)) {
+    if (!(key in props)) fail(`Invalid argument: ${key} is not allowed`);
+  }
+
+  // Reject missing required arguments.
+  for (const req of schema.required || []) {
+    if (!(req in args)) fail(`Missing argument: ${req}`);
+  }
+
+  switch (name) {
+    case 'begin_session': {
+      requireNonEmptyString(args.session_id, 'session_id');
+      sessions.set(args.session_id, new Map());
+      return ok(`session ${args.session_id} started`);
+    }
+    case 'put_value': {
+      requireNonEmptyString(args.session_id, 'session_id');
+      requireNonEmptyString(args.key, 'key');
+      requireString(args.value, 'value');
+      const store = sessions.get(args.session_id);
+      if (!store) fail(`No such session: ${args.session_id}`);
+      store.set(args.key, args.value);
+      return ok(`stored ${args.key} in session ${args.session_id}`);
+    }
+    case 'get_value': {
+      requireNonEmptyString(args.session_id, 'session_id');
+      requireNonEmptyString(args.key, 'key');
+      const store = sessions.get(args.session_id);
+      if (!store) fail(`No such session: ${args.session_id}`);
+      if (!store.has(args.key)) {
+        fail(`No such key: ${args.key} in session ${args.session_id}`);
+      }
+      return ok(store.get(args.key));
+    }
+    default:
+      fail(`Unknown tool: ${name}`);
+  }
+}
